export const title = "Can You Put a Projector on the Corner of a Small Desk?";
export const metaTitle = "Can a Projector Sit on a Small Desk Corner?";
export const metaDescription = "Check a projector’s lens position, throw requirements, supported image adjustments, ventilation, connections, and room routes.";
